(function(root){
const LINES=[{id:'sinnamwon-uiryeong',name:'345KV 신남원-의령',count:136},{id:'sabong-gaeyang',name:'154KV 사봉-개양',count:56}];
const PARTS=['항공구','항공등','애자련','지형','부지'];
const CHOICES={'항공등':['고광도','중광도','저광도'],'애자련':['내장','현수'],'지형':['산악지','논','도심지']};
const migrate=r=>({...r,lineId:r.lineId||LINES[0].id});
function latest(records,lineId,tower,part){return records.filter(r=>r.lineId===lineId&&r.tower===tower&&r.part===part).sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt))[0];}
function label(r){if(!r)return '미등록';if(r.part==='항공구')return Number.isInteger(r.ballCount)?r.ballCount+'개':'개수 미등록';if(r.part==='항공등')return r.lightIntensity||'광도 미등록';if(r.part==='애자련')return r.insulatorType||'형태 미등록';if(r.part==='지형')return r.terrain||'미등록';return r.land?.join(', ')||'미등록';}
function scene(records,lineId,tower){return {ballCount:latest(records,lineId,tower,'항공구')?.ballCount??0,lightIntensity:latest(records,lineId,tower,'항공등')?.lightIntensity||'',insulatorType:latest(records,lineId,tower,'애자련')?.insulatorType||'',terrain:latest(records,lineId,tower,'지형')?.terrain||''};}
function validate(data){if(data?.format!=='tower-ledger'||![1,2,3].includes(data.version)||!Array.isArray(data.records))throw Error('지원하지 않는 백업 형식입니다.');const ids=new Set();const records=data.records.map(r=>{r=data.version<3?migrate(r):r;const line=LINES.find(l=>l.id===r?.lineId);if(!line||typeof r.id!=='string'||!r.id||ids.has(r.id)||!Number.isInteger(r.tower)||r.tower<1||r.tower>line.count||!PARTS.includes(r.part)||typeof r.note!=='string'||r.note.length>3000||!Array.isArray(r.land)||!r.land.every(v=>['도심지','칡밭','산지','농경지','기타'].includes(v))||!Array.isArray(r.photos)||r.photos.length>8||!r.photos.every(v=>typeof v==='string'&&/^data:image\/jpeg;base64,[A-Za-z0-9+/]+=*$/.test(v))||typeof r.createdAt!=='string'||!Number.isFinite(Date.parse(r.createdAt)))throw Error('백업 기록이 올바르지 않습니다.');for(const [field,p] of [['lightIntensity','항공등'],['insulatorType','애자련'],['terrain','지형']])if(r[field]!==undefined&&r[field]!==''&&!CHOICES[p].includes(r[field]))throw Error('선택값이 올바르지 않습니다.');if(r.ballCount!==undefined&&(!Number.isInteger(r.ballCount)||r.ballCount<0||r.ballCount>100))throw Error('항공구 개수는 0~100개입니다.');ids.add(r.id);return r;});return records;}
const api={LINES,PARTS,CHOICES,migrate,latest,label,scene,validate};if(typeof module!=='undefined')module.exports=api;else root.LedgerModel=api;
})(globalThis);
